        "two-in-victim-room": "{room.in}는 한 사람만 있을 수 있어요. 바로 범인이에요. 둘 중 한 명을 다른 {rw.ro} 옮기세요.",
        "then": " 그다음 {room} 어딘가에 놓으세요.",
        "deduce": "남은 칸은 빛나는 칸 하나뿐이에요. {s}{s|c:을|v:를} 그 칸으로 옮기세요.",
        "deduce.in": "남은 칸은 {room}의 빛나는 칸 하나뿐이에요. {s}{s|c:을|v:를} 그 칸으로 옮기세요.",
        "narrow": "{s}{s|c:이|v:가} 있을 수 있는 칸이 아직 {n}칸 있어요. 모두 금색으로 빛나고 있어요. 연필로 점을 찍어 두고 하나씩 놓아 보세요. 칸마다 다른 진술이 여전히 맞는지 확인하면 돼요.",
        "narrow.in": "{s}{s|c:이|v:가} 있을 수 있는 칸이 {room.in} 아직 {n}칸 있어요. 모두 금색으로 빛나고 있어요. 연필로 점을 찍어 두고 하나씩 놓아 보세요. 칸마다 다른 진술이 여전히 맞는지 확인하면 돼요.",
        "done": "모두 제자리에 있어요. 확인을 누른 다음, {room.in}서 피해자와 단둘이 있던 사람을 지목하세요."
